                     upper = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("afni.dot", args = args, demean = demean, docoef = docoef, docor = docor, dodice = dodice, dodot = dodot, doeta2 = doeta2, dosums = dosums, full = full, in_files = in_files, mask = mask, mrange = mrange, out_file = out_file, show_labels = show_labels, upper = upper, .cwd = .cwd, .env = .env, .container = .container)
  ni_run(call, dry_run = dry_run, echo = echo)
}

#' AFNI ECM
