#' @param in_files Character or numeric vector. list of tuples of 3D warps and associated functions **Required.**
#' @param args Character. Additional parameters to the command
#' @param expad Integer. Pad the nonlinear warps by the given number of voxels in all directions. The warp displacements are extended by linear extrapolation from the faces of the input grid..
#' @param interp Character; one of: "wsinc5", "linear", "quintic". specify a different interpolation method than might be used for the warp
#' @param inv_warp Logical. invert the final warp before output
#' @param out_file Character; file path. output image file name
#' @param space Character. string to attach to the output dataset as its atlas space marker.
#' @param verb Logical. be verbose
#' @param .cwd Working directory override.
#' @param .env Named character vector of environment variables.
#' @param .container Container configuration list.
#' @param dry_run Logical; preview command without executing.
#' @param echo Logical; echo stdout/stderr in real time.
#' @return An `ni_result` object.
#' @export
ni_afni_nwarp_cat <- function(in_files,
                     args = NULL,
                     expad = NULL,
                     interp = "wsinc5",
                     inv_warp = NULL,
                     out_file = NULL,
                     space = NULL,
                     verb = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("afni.nwarp_cat", in_files = in_files, args = args, expad = expad, interp = interp, inv_warp = inv_warp, out_file = out_file, space = space, verb = verb, .cwd = .cwd, .env = .env, .container = .container)
  ni_run(call, dry_run = dry_run, echo = echo)
}

