#' AFNI Zeropad
#'
#' Adds planes of zeros to a dataset (i.e., pads it out).
#'
#' @param in_files Character; file path. input dataset **Required.**
#' @param A Integer. adds 'n' planes of zero at the Anterior edge
#' @param AP Integer. specify that planes should be added or cut symmetrically to make the resulting volume haveN slices in the anterior-posterior direction
#' @param I Integer. adds 'n' planes of zero at the Inferior edge
#' @param IS Integer. specify that planes should be added or cut symmetrically to make the resulting volume haveN slices in the inferior-superior direction
#' @param L Integer. adds 'n' planes of zero at the Left edge
#' @param P Integer. adds 'n' planes of zero at the Posterior edge
#' @param R Integer. adds 'n' planes of zero at the Right edge
#' @param RL Integer. specify that planes should be added or cut symmetrically to make the resulting volume haveN slices in the right-left direction
#' @param S Integer. adds 'n' planes of zero at the Superior edge
#' @param args Character. Additional parameters to the command
#' @param master Character; file path. match the volume described in dataset 'mset', where mset must have the same orientation and grid spacing as dataset to be padded. the goal of -master is to make the output dataset from 3dZeropad match the spatial 'extents' of mset by adding or subtracting slices as needed. You can't use -I,-S,..., or -mm with -master
#' @param mm Logical. pad counts 'n' are in mm instead of slices, where each 'n' is an integer and at least 'n' mm of slices will be added/removed; e.g., n =  3 and slice thickness = 2.5 mm ==> 2 slices added
#' @param out_file Character; file path. output dataset prefix name (default 'zeropad')
#' @param z Integer. adds 'n' planes of zero on EACH of the dataset z-axis (slice-direction) faces
#' @param .cwd Working directory override.
#' @param .env Named character vector of environment variables.
#' @param .container Container configuration list.
#' @param dry_run Logical; preview command without executing.
#' @param echo Logical; echo stdout/stderr in real time.
#' @return An `ni_result` object.
#' @export
ni_afni_zeropad <- function(in_files,
                     A = NULL,
                     AP = NULL,
                     I = NULL,
                     IS = NULL,
                     L = NULL,
                     P = NULL,
                     R = NULL,
                     RL = NULL,
                     S = NULL,
                     args = NULL,
                     master = NULL,
                     mm = NULL,
                     out_file = NULL,
                     z = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("afni.zeropad", in_files = in_files, A = A, AP = AP, I = I, IS = IS, L = L, P = P, R = R, RL = RL, S = S, args = args, master = master, mm = mm, out_file = out_file, z = z, .cwd = .cwd, .env = .env, .container = .container)
  ni_run(call, dry_run = dry_run, echo = echo)
}

