#' ANTS JointFusion
#'
#' An image fusion algorithm.
#'
#' @param atlas_image Character or numeric vector. The atlas image (or multimodal atlas images) assumed to be aligned to a common image domain. **Required.**
#' @param atlas_segmentation_image Character or numeric vector. The atlas segmentation images. For performing label fusion the number of specified segmentations should be identical to the number of atlas image sets. **Required.**
#' @param target_image Character or numeric vector. The target image (or multimodal target images) assumed to be aligned to a common image domain. **Required.**
#' @param alpha Numeric. Regularization term added to matrix Mx for calculating the inverse. Default = 0.1
#' @param args Character. Additional parameters to the command
#' @param beta Numeric. Exponent for mapping intensity difference to the joint error. Default = 2.0
#' @param constrain_nonnegative Logical. Constrain solution to non-negative weights.
#' @param dimension Character; one of: "3", "2", "4". This option forces the image to be treated as a specified-dimensional image. If not specified, the program tries to infer the dimensionality from the input image.
#' @param exclusion_image_label Character or numeric vector. Specify a label for the exclusion region.
#' @param mask_image Character; file path. If a mask image is specified, fusion is only performed in the mask region.
#' @param out_label_fusion Character; file path. The output label fusion image.
#' @param patch_metric Character; one of: "PC", "MSQ". Metric to be used in determining the most similar neighborhood patch. Options include Pearson's correlation (PC) and mean squares (MSQ). Default = PC (Pearson correlation).
#' @param patch_radius Character or numeric vector. Patch radius for similarity measures. Default: 2x2x2
#' @param retain_atlas_voting_images Logical. Retain atlas voting images. Default = false
#' @param retain_label_posterior_images Logical. Retain label posterior probability images. Requires atlas segmentations to be specified. Default = false
#' @param search_radius Character or numeric vector. Search radius for similarity measures. Default = 3x3x3. One can also specify an image where the value at the voxel specifies the isotropic search radius at that voxel.
#' @param verbose Logical. Verbose output.
#' @param .cwd Working directory override.
#' @param .env Named character vector of environment variables.
#' @param .container Container configuration list.
#' @param dry_run Logical; preview command without executing.
#' @param echo Logical; echo stdout/stderr in real time.
#' @return An `ni_result` object.
#' @export
ni_ants_joint_fusion <- function(atlas_image,
                     atlas_segmentation_image,
                     target_image,
                     alpha = 0.1,
                     args = NULL,
                     beta = 2,
                     constrain_nonnegative = FALSE,
                     dimension = NULL,
                     exclusion_image_label = NULL,
                     mask_image = NULL,
                     out_label_fusion = NULL,
                     patch_metric = NULL,
                     patch_radius = NULL,
                     retain_atlas_voting_images = FALSE,
                     retain_label_posterior_images = FALSE,
                     search_radius = 3,
                     search_radius = 3,
                     search_radius = 3,
                     verbose = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("ants.joint_fusion", atlas_image = atlas_image, atlas_segmentation_image = atlas_segmentation_image, target_image = target_image, alpha = alpha, args = args, beta = beta, constrain_nonnegative = constrain_nonnegative, dimension = dimension, exclusion_image_label = exclusion_image_label, mask_image = mask_image, out_label_fusion = out_label_fusion, patch_metric = patch_metric, patch_radius = patch_radius, retain_atlas_voting_images = retain_atlas_voting_images, retain_label_posterior_images = retain_label_posterior_images, search_radius = search_radius, verbose = verbose, .cwd = .cwd, .env = .env, .container = .container)
  ni_run(call, dry_run = dry_run, echo = echo)
}

#' ANTS KellyKapowski
#'
#' Nipype Interface to ANTs' KellyKapowski, also known as DiReCT.
#'
#' @param segmentation_image Character; file path. A segmentation image must be supplied labeling the gray and white matters. Default values = 2 and 3, respectively. **Required.**
#' @param args Character. Additional parameters to the command
#' @param convergence Character. Convergence is determined by fitting a line to the normalized energy profile of the last N iterations (where N is specified by the window size) and determining the slope which is then compared with the convergence threshold.
#' @param cortical_thickness Character; file path. Filename for the cortical thickness.
#' @param dimension Character; one of: "3", "2". image dimension (2 or 3)
#' @param gradient_step Numeric. Gradient step size for the optimization.
#' @param gray_matter_prob_image Character; file path. In addition to the segmentation image, a gray matter probability image can be used. If no such image is supplied, one is created using the segmentation image and a variance of 1.0 mm.
#' @param max_invert_displacement_field_iters Integer. Maximum number of iterations for estimating the invertdisplacement field.
#' @param number_integration_points Integer. Number of compositions of the diffeomorphism per iteration.
#' @param smoothing_variance Numeric. Defines the Gaussian smoothing of the hit and total images.
#' @param smoothing_velocity_field Numeric. Defines the Gaussian smoothing of the velocity field (default = 1.5). If the b-spline smoothing option is chosen, then this defines the isotropic mesh spacing for the smoothing spline (default = 15).
#' @param thickness_prior_estimate Numeric. Provides a prior constraint on the final thickness measurement in mm.
#' @param thickness_prior_image Character; file path. An image containing spatially varying prior thickness values.
#' @param use_bspline_smoothing Logical. Sets the option for B-spline smoothing of the velocity field.
#' @param white_matter_prob_image Character; file path. In addition to the segmentation image, a white matter probability image can be used. If no such image is supplied, one is created using the segmentation image and a variance of 1.0 mm.
#' @param .cwd Working directory override.
#' @param .env Named character vector of environment variables.
#' @param .container Container configuration list.
#' @param dry_run Logical; preview command without executing.
#' @param echo Logical; echo stdout/stderr in real time.
#' @return An `ni_result` object.
#' @export
ni_ants_kelly_kapowski <- function(segmentation_image,
                     args = NULL,
                     convergence = "[50,0.001,10]",
                     cortical_thickness = NULL,
                     dimension = 3,
                     gradient_step = 0.025,
                     gray_matter_prob_image = NULL,
                     max_invert_displacement_field_iters = 20,
                     number_integration_points = 10,
                     smoothing_variance = 1,
                     smoothing_velocity_field = 1.5,
                     thickness_prior_estimate = 10,
                     thickness_prior_image = NULL,
                     use_bspline_smoothing = NULL,
                     white_matter_prob_image = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("ants.kelly_kapowski", segmentation_image = segmentation_image, args = args, convergence = convergence, cortical_thickness = cortical_thickness, dimension = dimension, gradient_step = gradient_step, gray_matter_prob_image = gray_matter_prob_image, max_invert_displacement_field_iters = max_invert_displacement_field_iters, number_integration_points = number_integration_points, smoothing_variance = smoothing_variance, smoothing_velocity_field = smoothing_velocity_field, thickness_prior_estimate = thickness_prior_estimate, thickness_prior_image = thickness_prior_image, use_bspline_smoothing = use_bspline_smoothing, white_matter_prob_image = white_matter_prob_image, .cwd = .cwd, .env = .env, .container = .container)
  ni_run(call, dry_run = dry_run, echo = echo)
}

