                     shrink = NULL,
                     stop = NULL,
                     transform = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("freesurfer.mni_bias_correction", in_file = in_file, args = args, distance = distance, iterations = iterations, mask = mask, no_rescale = no_rescale, out_file = out_file, protocol_iterations = protocol_iterations, shrink = shrink, stop = stop, transform = transform, .cwd = .cwd, .env = .env, .container = .container)
