                     target_file,
                     args = NULL,
                     est_int_scale = NULL,
                     force_double = NULL,
                     force_float = NULL,
                     half_source = NULL,
                     half_source_xfm = NULL,
                     half_targ = NULL,
                     half_targ_xfm = NULL,
                     half_weights = NULL,
                     high_iterations = NULL,
                     in_xfm_file = NULL,
                     init_orient = NULL,
                     iteration_thresh = NULL,
                     least_squares = NULL,
                     mask_source = NULL,
                     mask_target = NULL,
                     max_iterations = NULL,
                     no_init = NULL,
                     no_multi = NULL,
                     out_reg_file = TRUE,
                     outlier_limit = NULL,
                     registered_file = NULL,
                     subsample_thresh = NULL,
                     trans_only = NULL,
                     weights_file = NULL,
                     write_vo2vox = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("freesurfer.robust_register", auto_sens = auto_sens, outlier_sens = outlier_sens, source_file = source_file, target_file = target_file, args = args, est_int_scale = est_int_scale, force_double = force_double, force_float = force_float, half_source = half_source, half_source_xfm = half_source_xfm, half_targ = half_targ, half_targ_xfm = half_targ_xfm, half_weights = half_weights, high_iterations = high_iterations, in_xfm_file = in_xfm_file, init_orient = init_orient, iteration_thresh = iteration_thresh, least_squares = least_squares, mask_source = mask_source, mask_target = mask_target, max_iterations = max_iterations, no_init = no_init, no_multi = no_multi, out_reg_file = out_reg_file, outlier_limit = outlier_limit, registered_file = registered_file, subsample_thresh = subsample_thresh, trans_only = trans_only, weights_file = weights_file, write_vo2vox = write_vo2vox, .cwd = .cwd, .env = .env, .container = .container)
