                     fixed_timepoint = NULL,
                     in_intensity_scales = NULL,
                     initial_timepoint = NULL,
                     initial_transforms = NULL,
                     intensity_scaling = NULL,
                     no_iteration = NULL,
                     scaled_intensity_outputs = NULL,
                     subsample_threshold = NULL,
                     transform_outputs = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
