                     bg_threshold = NULL,
                     cov_weight = NULL,
                     dim = NULL,
                     dim_est = NULL,
                     epsilon = NULL,
                     epsilonS = NULL,
                     log_power = NULL,
                     mask = NULL,
                     max_restart = NULL,
                     maxit = NULL,
                     migp = NULL,
                     migpN = NULL,
                     migp_factor = NULL,
                     migp_shuffle = NULL,
                     mix = NULL,
                     mm_thresh = NULL,
                     no_bet = NULL,
                     no_mask = NULL,
                     no_mm = NULL,
                     non_linearity = NULL,
                     num_ICs = NULL,
                     out_all = NULL,
                     out_dir = NULL,
                     out_mean = NULL,
                     out_orig = NULL,
                     out_pca = NULL,
                     out_stats = NULL,
                     out_unmix = NULL,
                     out_white = NULL,
                     pbsc = NULL,
                     rem_cmp = NULL,
                     remove_deriv = NULL,
                     report = NULL,
                     report_maps = NULL,
                     s_con = NULL,
                     s_des = NULL,
                     sep_vn = NULL,
                     sep_whiten = NULL,
                     smode = NULL,
                     t_con = NULL,
                     t_des = NULL,
                     tr_sec = NULL,
                     update_mask = NULL,
                     var_norm = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("fsl.melodic", in_files = in_files, ICs = ICs, approach = approach, args = args, bg_image = bg_image, bg_threshold = bg_threshold, cov_weight = cov_weight, dim = dim, dim_est = dim_est, epsilon = epsilon, epsilonS = epsilonS, log_power = log_power, mask = mask, max_restart = max_restart, maxit = maxit, migp = migp, migpN = migpN, migp_factor = migp_factor, migp_shuffle = migp_shuffle, mix = mix, mm_thresh = mm_thresh, no_bet = no_bet, no_mask = no_mask, no_mm = no_mm, non_linearity = non_linearity, num_ICs = num_ICs, out_all = out_all, out_dir = out_dir, out_mean = out_mean, out_orig = out_orig, out_pca = out_pca, out_stats = out_stats, out_unmix = out_unmix, out_white = out_white, pbsc = pbsc, rem_cmp = rem_cmp, remove_deriv = remove_deriv, report = report, report_maps = report_maps, s_con = s_con, s_des = s_des, sep_vn = sep_vn, sep_whiten = sep_whiten, smode = smode, t_con = t_con, t_des = t_des, tr_sec = tr_sec, update_mask = update_mask, var_norm = var_norm, .cwd = .cwd, .env = .env, .container = .container)
