#' FSL TOPUP
#'
#' Interface for FSL topup, a tool for estimating and correcting
#'
#' @param encoding_direction Character or numeric vector. encoding direction for automatic generation of encoding_file **Required.**
#' @param encoding_file Character; file path. name of text file with PE directions/times **Required.**
#' @param in_file Character; file path. name of 4D file with images **Required.**
#' @param readout_times Character or numeric vector. readout times (dwell times by # phase-encode steps minus 1) **Required.**
#' @param args Character. Additional parameters to the command
#' @param config Character. Name of config file specifying command line arguments
#' @param estmov Character; one of: "1", "0". estimate movements if set
#' @param fwhm Numeric. FWHM (in mm) of gaussian smoothing kernel
#' @param interp Character; one of: "spline", "linear". Image interpolation model, linear or spline.
#' @param max_iter Integer. max # of non-linear iterations
#' @param minmet Character; one of: "0", "1". Minimisation method 0=Levenberg-Marquardt, 1=Scaled Conjugate Gradient
#' @param numprec Character; one of: "double", "float". Precision for representing Hessian, double or float.
#' @param out_base Character; file path. base-name of output files (spline coefficients (Hz) and movement parameters)
#' @param out_corrected Character; file path. name of 4D image file with unwarped images
#' @param out_field Character; file path. name of image file with field (Hz)
#' @param out_jac_prefix Character. prefix for the warpfield images
#' @param out_logfile Character; file path. name of log-file
#' @param out_mat_prefix Character. prefix for the realignment matrices
#' @param out_warp_prefix Character. prefix for the warpfield images (in mm)
#' @param reg_lambda Numeric. Weight of regularisation, default depending on --ssqlambda and --regmod switches.
#' @param regmod Character; one of: "bending_energy", "membrane_energy". Regularisation term implementation. Defaults to bending_energy. Note that the two functions have vastly different scales. The membrane energy is based on the first derivatives and the bending energy on the second derivatives. The second derivatives will typically be much smaller than the first derivatives, so input lambda will have to be larger for bending_energy to yield approximately the same level of regularisation.
#' @param regrid Character; one of: "1", "0". If set (=1), the calculations are done in a different grid
#' @param scale Character; one of: "0", "1". If set (=1), the images are individually scaled to a common mean
#' @param splineorder Integer. order of spline, 2->Qadratic spline, 3->Cubic spline
#' @param ssqlambda Character; one of: "1", "0". Weight lambda by the current value of the ssd. If used (=1), the effective weight of regularisation term becomes higher for the initial iterations, therefore initial steps are a little smoother than they would without weighting. This reduces the risk of finding a local minimum.
#' @param subsamp Integer. sub-sampling scheme
#' @param warp_res Numeric. (approximate) resolution (in mm) of warp basis for the different sub-sampling levels
#' @param .cwd Working directory override.
#' @param .env Named character vector of environment variables.
#' @param .container Container configuration list.
#' @param dry_run Logical; preview command without executing.
#' @param echo Logical; echo stdout/stderr in real time.
#' @return An `ni_result` object.
#' @export
ni_fsl_topup <- function(encoding_direction,
                     encoding_file,
                     in_file,
                     readout_times,
                     args = NULL,
                     config = "b02b0.cnf",
                     estmov = NULL,
                     fwhm = NULL,
                     interp = NULL,
                     max_iter = NULL,
                     minmet = NULL,
                     numprec = NULL,
                     out_base = NULL,
                     out_corrected = NULL,
                     out_field = NULL,
                     out_jac_prefix = "jac",
                     out_logfile = NULL,
                     out_mat_prefix = "xfm",
                     out_warp_prefix = "warpfield",
                     reg_lambda = NULL,
                     regmod = NULL,
                     regrid = NULL,
                     scale = NULL,
                     splineorder = NULL,
                     ssqlambda = NULL,
                     subsamp = NULL,
                     warp_res = NULL,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("fsl.topup", encoding_direction = encoding_direction, encoding_file = encoding_file, in_file = in_file, readout_times = readout_times, args = args, config = config, estmov = estmov, fwhm = fwhm, interp = interp, max_iter = max_iter, minmet = minmet, numprec = numprec, out_base = out_base, out_corrected = out_corrected, out_field = out_field, out_jac_prefix = out_jac_prefix, out_logfile = out_logfile, out_mat_prefix = out_mat_prefix, out_warp_prefix = out_warp_prefix, reg_lambda = reg_lambda, regmod = regmod, regrid = regrid, scale = scale, splineorder = splineorder, ssqlambda = ssqlambda, subsamp = subsamp, warp_res = warp_res, .cwd = .cwd, .env = .env, .container = .container)
  ni_run(call, dry_run = dry_run, echo = echo)
}

