                     burn_in_no_ard = 0,
                     cnlinear = NULL,
                     f0_ard = NULL,
                     f0_noard = NULL,
                     force_dir = TRUE,
                     fudge = NULL,
                     gradnonlin = NULL,
                     logdir = ".",
                     model = NULL,
                     n_jumps = 5000,
                     no_ard = NULL,
                     no_spat = NULL,
                     non_linear = NULL,
                     rician = NULL,
                     sample_every = 1,
                     seed = NULL,
                     update_proposal_every = 40,
                     .cwd = NULL,
                     .env = NULL,
                     .container = NULL,
                     dry_run = FALSE,
                     echo = interactive()) {
  call <- ni_call("fsl.x_fibres5", bvals = bvals, bvecs = bvecs, dwi = dwi, mask = mask, n_fibres = n_fibres, all_ard = all_ard, args = args, burn_in = burn_in, burn_in_no_ard = burn_in_no_ard, cnlinear = cnlinear, f0_ard = f0_ard, f0_noard = f0_noard, force_dir = force_dir, fudge = fudge, gradnonlin = gradnonlin, logdir = logdir, model = model, n_jumps = n_jumps, no_ard = no_ard, no_spat = no_spat, non_linear = non_linear, rician = rician, sample_every = sample_every, seed = seed, update_proposal_every = update_proposal_every, .cwd = .cwd, .env = .env, .container = .container)
  ni_run(call, dry_run = dry_run, echo = echo)
}

